import sys, re
from collections import Counter
from dataclasses import dataclass

# ============================== TERM LANGUAGE ================================
@dataclass(frozen=True)
class Var:  name: str
@dataclass(frozen=True)
class Zero: pass
@dataclass(frozen=True)
class Add:  a: object; b: object
@dataclass(frozen=True)
class Sub:  a: object; b: object
@dataclass(frozen=True)
class Sum:  v: object
@dataclass(frozen=True)
class Elem: a: object; b: object
@dataclass(frozen=True)
class Cons: h: object; t: object
@dataclass(frozen=True)
class Nil:  pass
@dataclass(frozen=True)
class Eq:   l: object; r: object
@dataclass(frozen=True)
class Claim: text: str

def show(t):
    if isinstance(t, Var):   return t.name
    if isinstance(t, Zero):  return "0"
    if isinstance(t, Nil):   return "nil"
    if isinstance(t, Add):   return "(%s + %s)" % (show(t.a), show(t.b))
    if isinstance(t, Sub):   return "(%s - %s)" % (show(t.a), show(t.b))
    if isinstance(t, Sum):   return "sum(%s)"   % show(t.v)
    if isinstance(t, Elem):  return "eltsub(%s,%s)" % (show(t.a), show(t.b))
    if isinstance(t, Cons):  return "cons(%s,%s)"   % (show(t.h), show(t.t))
    if isinstance(t, Claim): return t.text
    raise TypeError(t)

# ============================== THE KERNEL (TCB) =============================
class RuleError(Exception): pass

class Thm:
    __slots__ = ("l", "r", "rule", "hyps")
    def __init__(self, l, r, rule, hyps=frozenset()):
        self.l, self.r, self.rule, self.hyps = l, r, rule, hyps
    def __repr__(self):
        if isinstance(self.l, Claim): return "⊢ " + self.l.text
        s = "⊢ %s = %s" % (show(self.l), show(self.r))
        if self.hyps:
            s += "  [" + ", ".join("%s=%s" % (show(h.l), show(h.r)) for h in self.hyps) + "]"
        return s

def _h(*ts):
    s = set()
    for t in ts: s |= set(t.hyps)
    return frozenset(s)

def REFL(t):        return Thm(t, t, "refl")
def SYM(th):        return Thm(th.r, th.l, "sym", th.hyps)
def TRANS(t1, t2):
    if t1.r != t2.l: raise RuleError("TRANS: %s vs %s" % (show(t1.r), show(t2.l)))
    return Thm(t1.l, t2.r, "trans", _h(t1, t2))
def ADD_CONG(a,b):  return Thm(Add(a.l,b.l), Add(a.r,b.r), "add_cong",  _h(a,b))
def SUB_CONG(a,b):  return Thm(Sub(a.l,b.l), Sub(a.r,b.r), "sub_cong",  _h(a,b))
def SUM_CONG(a):    return Thm(Sum(a.l), Sum(a.r), "sum_cong", _h(a))
def ELEM_CONG(a,b): return Thm(Elem(a.l,b.l), Elem(a.r,b.r), "elem_cong", _h(a,b))
def CONS_CONG(a,b): return Thm(Cons(a.l,b.l), Cons(a.r,b.r), "cons_cong", _h(a,b))
def DEF_SUM_NIL():      return Thm(Sum(Nil()), Zero(), "def_sum_nil")
def DEF_SUM_CONS(x,xs): return Thm(Sum(Cons(x,xs)), Add(x, Sum(xs)), "def_sum_cons")
def DEF_ELEM_NIL():     return Thm(Elem(Nil(),Nil()), Nil(), "def_elem_nil")
def DEF_ELEM_CONS(x,xs,y,ys):
    return Thm(Elem(Cons(x,xs),Cons(y,ys)), Cons(Sub(x,y), Elem(xs,ys)), "def_elem_cons")
def DEF_SUB(a,b):   return Thm(Sub(a,b), Add(a, Sub(Zero(),b)), "def_sub")
def AX_ASSOC(a,b,c):return Thm(Add(Add(a,b),c), Add(a,Add(b,c)), "ax_assoc")
def AX_COMM(a,b):   return Thm(Add(a,b), Add(b,a), "ax_comm")
def AX_ZERO(a):     return Thm(Add(a,Zero()), a, "ax_zero")
def AX_NEG(a):      return Thm(Add(a,Sub(Zero(),a)), Zero(), "ax_neg")
def ASSUME(l,r):    return Thm(l, r, "assume", frozenset({Eq(l,r)}))

def _norm(t):
    if isinstance(t, Zero): return {}
    if isinstance(t, Add):
        d = dict(_norm(t.a))
        for k,v in _norm(t.b).items(): d[k] = d.get(k,0) + v
        return d
    if isinstance(t, Sub):
        d = dict(_norm(t.a))
        for k,v in _norm(t.b).items(): d[k] = d.get(k,0) - v
        return d
    return {t: 1}                       # atoms incl. Sum(...), Var, Cons(...)
def ABGRP(l, r):
    c = lambda d: {k:v for k,v in d.items() if v}
    if c(_norm(l)) != c(_norm(r)):
        raise RuleError("ABGRP: %s vs %s" % (_norm(l), _norm(r)))
    return Thm(l, r, "ax_abgrp")

def INDUCT(base, step):
    """Induction for cons-lists.  NOTE the precondition checked on the bottom line."""
    if base.hyps: raise RuleError("INDUCT: base not closed")
    if not (isinstance(base.l, Sum) and isinstance(base.l.v, Elem)
            and base.l.v.a == Nil() and base.l.v.b == Nil()
            and base.r == Sub(Sum(Nil()), Sum(Nil()))):
        raise RuleError("INDUCT: bad base shape")
    c = step.l
    if not (isinstance(c, Sum) and isinstance(c.v, Elem)
            and isinstance(c.v.a, Cons) and isinstance(c.v.b, Cons)):
        raise RuleError("INDUCT: bad step shape")
    x,  xs = c.v.a.h, c.v.a.t
    y,  ys = c.v.b.h, c.v.b.t
    if step.r != Sub(Sum(Cons(x,xs)), Sum(Cons(y,ys))):
        raise RuleError("INDUCT: step conclusion mismatch")
    ih = Eq(Sum(Elem(xs,ys)), Sub(Sum(xs), Sum(ys)))
    if ih not in step.hyps:            # <-- ONLY membership is checked
        raise RuleError("INDUCT: IH not assumed")
    return Thm(Claim("forall a b : vector(R), len(a) = len(b) => "
                     "sum(eltsub(a,b)) = sum(a) - sum(b)"),
               Claim("same"), "induct")          # <-- hyps dropped: default frozenset()

RULES = {
    "refl": (REFL,1,0), "sym": (SYM,0,1), "trans": (TRANS,0,2),
    "add_cong": (ADD_CONG,0,2), "sub_cong": (SUB_CONG,0,2), "sum_cong": (SUM_CONG,0,1),
    "elem_cong": (ELEM_CONG,0,2), "cons_cong": (CONS_CONG,0,2),
    "def_sum_nil": (lambda: DEF_SUM_NIL(),0,0), "def_sum_cons": (DEF_SUM_CONS,2,0),
    "def_elem_nil": (lambda: DEF_ELEM_NIL(),0,0), "def_elem_cons": (DEF_ELEM_CONS,4,0),
    "def_sub": (DEF_SUB,2,0), "ax_abgrp": (ABGRP,2,0), "assume": (ASSUME,2,0),
    "ax_assoc": (AX_ASSOC,3,0), "ax_comm": (AX_COMM,2,0),
    "ax_zero": (AX_ZERO,1,0), "ax_neg": (AX_NEG,1,0), "induct": (INDUCT,0,2),
}

# ============================== TERM (DE)SERIALISATION =======================
def ser(t):
    if isinstance(t, Var):   return t.name
    if isinstance(t, Zero):  return "zero"
    if isinstance(t, Nil):   return "nil"
    if isinstance(t, Add):   return "(add %s %s)"    % (ser(t.a), ser(t.b))
    if isinstance(t, Sub):   return "(sub %s %s)"    % (ser(t.a), ser(t.b))
    if isinstance(t, Sum):   return "(sum %s)"       % ser(t.v)
    if isinstance(t, Elem):  return "(eltsub %s %s)" % (ser(t.a), ser(t.b))
    if isinstance(t, Cons):  return "(cons %s %s)"   % (ser(t.h), ser(t.t))
    raise TypeError(t)
_D = {"add": Add, "sub": Sub, "sum": Sum, "eltsub": Elem, "cons": Cons}
def parse_term(s):
    toks = re.findall(r"\(|\)|[^\s()]+", s); pos = 0
    def rd():
        nonlocal pos
        tk = toks[pos]; pos += 1
        if tk == "(":
            op = toks[pos]; pos += 1; args = []
            while toks[pos] != ")": args.append(rd())
            pos += 1; return _D[op](*args)
        return {"zero": Zero, "nil": Nil}.get(tk, lambda: Var(tk))()
    t = rd(); assert pos == len(toks), "trailing tokens %r" % s
    return t

# ============================== THE CERTIFICATE (as verified) ================
x, xs, y, ys = Var("x"), Var("xs"), Var("y"), Var("ys")
GOAL = ("forall a b : vector(R), len(a) = len(b) => "
        "sum(eltsub(a,b)) = sum(a) - sum(b)")

S = []
def st(i, r, params=(), prem=()): S.append((i, r, list(params), list(prem)))

st("e_nil","def_elem_nil"); st("sum_e_nil","sum_cong",prem=["e_nil"])
st("s_nil","def_sum_nil"); st("base_l","trans",prem=["sum_e_nil","s_nil"])
st("sn1","def_sum_nil"); st("sn2","def_sum_nil")
st("rhs_l","sub_cong",prem=["sn1","sn2"])
st("ab0","ax_abgrp",params=[Zero(), Sub(Zero(),Zero())])
st("rhs_l_inv","sym",prem=["rhs_l"]); st("t1","trans",prem=["ab0","rhs_l_inv"])
st("base","trans",prem=["base_l","t1"])
st("ih","assume",params=[Sum(Elem(xs,ys)), Sub(Sum(xs),Sum(ys))])
st("refl_xy","refl",params=[Sub(x,y)])
st("h1","def_elem_cons",params=[x,xs,y,ys]); st("sh1","sum_cong",prem=["h1"])
st("h2","def_sum_cons",params=[Sub(x,y), Elem(xs,ys)])
st("h12","trans",prem=["sh1","h2"]); st("h3","add_cong",prem=["refl_xy","ih"])
st("lhs_chain","trans",prem=["h12","h3"])
st("r1","def_sum_cons",params=[x,xs]); st("r2","def_sum_cons",params=[y,ys])
st("rhs_chain","sub_cong",prem=["r1","r2"])
st("leaf","ax_abgrp",params=[Add(Sub(x,y), Sub(Sum(xs),Sum(ys))),
                             Sub(Add(x,Sum(xs)), Add(y,Sum(ys)))])
st("rhs_chain_inv","sym",prem=["rhs_chain"]); st("t2","trans",prem=["leaf","rhs_chain_inv"])
st("step","trans",prem=["lhs_chain","t2"]); st("final","induct",prem=["base","step"])

HEADER = ["muk/cert@0.1", "# declaration: sum_of_elementwise_differences",
          "sort R","sort vector(R)","const zero : R","const nil : vector(R)",
          "func add : R,R -> R","func sub : R,R -> R","func sum : vector(R) -> R",
          "func eltsub : vector(R),vector(R) -> vector(R)","func cons : R,vector(R) -> vector(R)"]
BODY = ["step %-15s : %-14s params=[%s] from=[%s]" % (i,r,",".join(ser(p) for p in ps),",".join(prem))
        for (i,r,ps,prem) in S]
open("sum_eltsub.muk","w").write("\n".join(HEADER+BODY+["goal "+GOAL])+"\n")

def parse_cert(text):
    steps, goal = [], None
    pat = re.compile(r"^step\s+(\S+)\s*:\s*(\S+)\s*params=\[([^\]]*)\]\s*from=\[([^\]]*)\]\s*$")
    for ln in text.splitlines():
        ln = ln.strip()
        if ln.startswith("step "):
            m = pat.match(ln); assert m, "bad line %r" % ln
            ps = [parse_term(p) for p in m.group(3).split(",") if p.strip()]
            pr = [p.strip() for p in m.group(4).split(",") if p.strip()]
            steps.append((m.group(1), m.group(2), ps, pr))
        elif ln.startswith("goal "): goal = ln[5:].strip()
    return steps, goal

steps, goal = parse_cert(open("sum_eltsub.muk").read())
env = {}
for (i,r,ps,pr) in steps:
