# ============================ 1. TERM LANGUAGE ================================
# Sorts:  R (Real), vector(R)   --  vector(R) ~= finite non-empty list of R
@dataclass(frozen=True)
class Var:
    name: str

@dataclass(frozen=True)
class Zero:
    pass

@dataclass(frozen=True)
class Add:
    a: object
    b: object

@dataclass(frozen=True)
