    a: object
    b: object

@dataclass(frozen=True)
class Sub:
    a: object
    b: object

@dataclass(frozen=True)
class Sum:          # sum : vector(R) -> R
    v: object

@dataclass(frozen=True)
class Elem:         # eltsub : vector(R) x vector(R) -> vector(R)
    a: object
    b: object

@dataclass(frozen=True)
class Cons:
    h: object
    t: object

@dataclass(frozen=True)
class Nil:
